<?php
require_once '../includes/auth.php';
require_once '../includes/db.php';
require_once '../includes/staff_attendance_helper.php';
require_once '../includes/staff_ledger_helper.php';
require_admin_user();
$user_id = (int)$_SESSION['user_id'];
ensure_staff_attendance_tables($conn); ensure_staff_ledger_table($conn);
$id=(int)($_GET['id']??0);
$stmt=mysqli_prepare($conn,"SELECT ms.*, s.name,s.staff_code,s.designation,l.txn_no,l.entry_date,l.note,w.wallet_name FROM staff_monthly_salaries ms INNER JOIN staff s ON s.id=ms.staff_id AND s.user_id=ms.user_id LEFT JOIN staff_ledger_entries l ON l.id=ms.paid_ledger_id AND l.user_id=ms.user_id LEFT JOIN wallets w ON w.id=ms.paid_wallet_id AND w.user_id=ms.user_id WHERE ms.id=? AND ms.user_id=? LIMIT 1");
mysqli_stmt_bind_param($stmt,'ii',$id,$user_id); mysqli_stmt_execute($stmt); $salary=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt));
if(!$salary || $salary['payment_status']!=='paid'){ http_response_code(404); exit('Paid salary voucher not found.'); }
?>
<!doctype html><html><head><meta charset="utf-8"><title>Salary Voucher <?= htmlspecialchars($salary['txn_no']) ?></title><style>body{margin:0;background:#eef2f7;color:#172033;font:15px Arial,sans-serif}.page{width:820px;margin:35px auto;background:#fff;padding:48px 54px;box-sizing:border-box;box-shadow:0 3px 16px #cbd3df}.top{display:flex;justify-content:space-between;border-bottom:3px solid #146ed8;padding-bottom:22px}.company{font-size:25px;font-weight:700;color:#0b3f78}.subtitle{color:#61738b;margin-top:7px}.voucher{text-align:right}.voucher h1{margin:0;color:#146ed8;font-size:24px}.badge{display:inline-block;background:#e0f5e6;color:#18723a;font-weight:bold;border-radius:14px;padding:5px 11px;margin-top:9px}.details{display:grid;grid-template-columns:1fr 1fr;gap:28px;margin:30px 0}.label{color:#61738b;font-size:11px;font-weight:bold;text-transform:uppercase;letter-spacing:1px;margin-bottom:8px}.name{font-size:20px;font-weight:bold;margin-bottom:6px}.box{border:1px solid #d9e2ee;padding:15px;line-height:1.7}.amount{background:#f0f7ff;border:1px solid #c9ddf5;margin-top:18px;padding:17px;display:flex;justify-content:space-between;font-size:20px;font-weight:bold;color:#0759b8}.signature{margin-top:70px;display:flex;justify-content:space-between;text-align:center}.signature div{width:220px;border-top:1px solid #4b5563;padding-top:9px;color:#44546a}.footer{margin-top:40px;padding-top:16px;border-top:1px solid #d9e2ee;text-align:center;color:#718096;font-size:12px}.print{position:fixed;right:25px;top:20px;background:#146ed8;color:#fff;border:0;padding:11px 18px;border-radius:5px;font-size:15px;cursor:pointer}@media print{body{background:#fff}.page{box-shadow:none;margin:0;width:100%}.print{display:none}}</style></head><body><button class="print" onclick="window.print()">Print Voucher</button><main class="page"><section class="top"><div><div class="company">You2 Technologies</div><div class="subtitle">Staff Salary Payment Voucher</div></div><div class="voucher"><h1>SALARY VOUCHER</h1><div><?= htmlspecialchars($salary['txn_no']) ?></div><span class="badge">PAID</span></div></section><section class="details"><div><div class="label">Received By</div><div class="box"><div class="name"><?= htmlspecialchars($salary['name']) ?></div><?= htmlspecialchars($salary['staff_code']) ?><br><?= htmlspecialchars($salary['designation']) ?></div></div><div><div class="label">Payment Details</div><div class="box"><strong>Salary Period:</strong> <?= date('F Y',mktime(0,0,0,(int)$salary['salary_month'],1,(int)$salary['salary_year'])) ?><br><strong>Payment Date:</strong> <?= date('d-m-Y',strtotime($salary['entry_date'])) ?><br><strong>Payment by:</strong> <?= htmlspecialchars($salary['wallet_name']) ?><br><strong>Attendance Cut:</strong> BDT <?= number_format((float)$salary['salary_cut_amount'],2) ?></div></div></section><div class="amount"><span>NET SALARY RECEIVED</span><span>BDT <?= number_format((float)$salary['generated_salary'],2) ?></span></div><?php if($salary['note']): ?><p><strong>Note:</strong> <?= htmlspecialchars($salary['note']) ?></p><?php endif; ?><section class="signature"><div>Prepared By</div><div>Authorized By</div><div>Received By (Staff Signature)</div></section><div class="footer">This is a system-generated salary payment voucher.</div></main><?php if(isset($_GET['paid'])): ?><script>if(window.opener){window.opener.location.reload();}</script><?php endif; ?></body></html>
